// Normaliza telefone — sempre com 55 na frente
function _normTel(t) {
  if (!t) return '';
  let _t = String(t).replace(/D/g, '');
  if (_t.startsWith('55') && _t.length >= 12) return _t;
  if (_t.length === 10 || _t.length === 11) return '55' + _t;
  return _t;
}

