            intencao: (_imIW?.transacao==='venda'?'comprar':_imIW?.transacao==='aluguel'?'alugar':_imIW?.transacao) || (mapa.transacao?.[0]?.valor==='venda'?'comprar':mapa.transacao?.[0]?.valor==='aluguel'?'alugar':mapa.transacao?.[0]?.valor) || '',
