// ── JOB_FOLLOWUPS — processa followUps pendentes vencidos ────────────────────
setInterval(async () => {
  try {
    const _leads = await lerLeadsData();
    const _users = (_cacheUsuarios || []);
    const _agora = Date.now();
    const BASE_URL = process.env.RENDER ? 'https://www.matchimoveis.ia.br' : (process.env.BASE_URL || 'http://localhost:3000');
    const EU = process.env.EVOLUTION_URL || 'https://match-evolution-api.onrender.com';
    const EK = process.env.EVOLUTION_KEY || 'match2025evolution';
    let _salvou = false;

    async function _enviarWA(instancia, numero, texto) {
      try {
        await fetch(EU + '/message/sendText/' + instancia, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json', 'apikey': EK },
          body: JSON.stringify({ number: numero, text: texto })
        });
      } catch(e) { console.error('[JOB FU] erro envio WA:', e.message); }
    }

    for (let i = 0; i < _leads.length; i++) {
      const lead = _leads[i];
      if (!lead.followUps || !lead.followUps.length) continue;

      const _userId = lead.userId || lead.corretorId || lead.codigoUsuario || '';
      const _user = _users.find(u => u.id === _userId);
      const _instancia = _user?.whatsappInstance || 'match-corretor';
      const _contato = (lead.telefone || lead.whatsapp || lead.contato || '').replace(/\D/g, '');

      let _mudou = false;

      for (let j = 0; j < lead.followUps.length; j++) {
        const fu = lead.followUps[j];
        if (fu.status !== 'pendente') continue;
        if (!fu.prazo || new Date(fu.prazo).getTime() > _agora) continue;

        console.log('[JOB FU] disparando:', fu.tipo, '| lead:', lead.nome || _contato);

        _leads[i].followUps[j].status = 'executado';
        _leads[i].followUps[j].executadoEm = new Date().toISOString();
        _mudou = true;

        if (!_contato || !_instancia) continue;

        consumir(_leads[i].userId || _leads[i].corretorId, 'followup_auto').catch(()=>{});
        if (fu.tipo === 'enviar_vitrine') {
          const _matches = (_leads[i].matchesAuto || _leads[i].matches || []).length;
          if (_matches === 0) continue; // não envia vitrine vazia
          const _link = BASE_URL + '/cliente/oferta/' + lead.id + '?userId=' + _userId;
          const { query: _qVitrineClaimFU } = require('./services/db');

          // WhatsApp e email são claims INDEPENDENTES — cada um só dispara
          // se conseguir marcar sua própria flag no banco agora (evita
          // corrida com o caminho inline de match-core.js, que só cobre
          // WhatsApp, e permite mandar só o email quando o WhatsApp já foi
          // pelo caminho rápido mas o email nunca tinha ido).
          let _claimWA = null;
          try {
            _claimWA = await _qVitrineClaimFU(
              "UPDATE leads SET vitrine_enviada=true, vitrine_enviada_em=NOW() WHERE id=$1 AND COALESCE(vitrine_enviada,false)=false RETURNING id",
              [lead.id]
            );
          } catch(e) { console.error('[JOB FU] erro claim vitrine WA:', e.message); }

          if (_claimWA && _claimWA.rows.length) {
            const _msg = 'Ola ' + (lead.nome || '') + '! Encontramos '
              + _matches + ' imove' + (_matches === 1 ? 'l' : 'is')
              + ' que combinam com o seu perfil.\n\nAcesse sua selecao personalizada:\n'
              + _link + '\n\nEscolha o imovel que mais gostou e agende sua visita! \n\n' + ((_user && _user.nome) ? _user.nome : 'Seu corretor') + ' - MatchImoveis';
            await _enviarWA(_instancia, _contato, _msg);
            _leads[i].vitrineEnviada = true;
            consumir(_leads[i].userId || _leads[i].corretorId, 'vitrine_whatsapp').catch(()=>{});
            _leads[i].vitrineEnviadaEm = new Date().toISOString();
            _leads[i].vitrineLink = _link;
            // Criar follow-up automático de 6h se não tiver visita
            if (!_leads[i].followUps) _leads[i].followUps = [];
            const _jaTemFUVitrine = _leads[i].followUps.some(f => f.tipo==='followup_vitrine' && f.status==='pendente');
            if (!_jaTemFUVitrine) {
              const _agora6h = Date.now();
              _leads[i].followUps.push({
                id: _agora6h.toString(),
                tipo: 'followup_vitrine',
                status: 'pendente',
                criadoEm: new Date(_agora6h).toISOString(),
                prazo: new Date(_agora6h + 6*3600*1000).toISOString()
              });
            }
          } else {
            console.log('[JOB FU] vitrine WhatsApp já enviada por outro caminho, pulando:', lead.nome || _contato);
          }

          const _emailLead = lead.email || lead.dados?.email || '';
          if (_emailLead) {
            let _claimEmail = null;
            try {
              _claimEmail = await _qVitrineClaimFU(
                "UPDATE leads SET vitrine_email_enviada=true, vitrine_email_enviada_em=NOW() WHERE id=$1 AND COALESCE(vitrine_email_enviada,false)=false RETURNING id",
                [lead.id]
              );
            } catch(e) { console.error('[JOB FU] erro claim vitrine email:', e.message); }
            if (_claimEmail && _claimEmail.rows.length) {
              try {
                const _msgEmail = 'Ola ' + (lead.nome || '') + '! Encontramos '
                  + _matches + ' imove' + (_matches === 1 ? 'l' : 'is')
                  + ' que combinam com o seu perfil.\n\nAcesse sua selecao personalizada:\n' + _link;
                const { enviarEmail } = require('./services/email');
                await enviarEmail({
                  para: _emailLead,
                  assunto: '🏠 Encontramos imóveis para você!',
                  html: `<div style="font-family:Arial,sans-serif;max-width:600px;margin:0 auto;padding:32px">
                    <h2 style="color:#FF385C">Olá, ${lead.nome||''}! 🏠</h2>
                    <p>Encontramos <strong>${_matches} imóvel(is)</strong> que combinam com o seu perfil.</p>
                    <a href="${_link}" style="display:inline-block;margin-top:16px;padding:14px 28px;background:#FF385C;color:#fff;text-decoration:none;border-radius:8px;font-weight:bold;font-size:16px">Ver minha seleção personalizada →</a>
                    <p style="margin-top:24px;color:#888;font-size:12px">Escolha o imóvel que mais gostou e agende sua visita!</p>
                  </div>`,
                  texto: _msgEmail,
                  tipo: 'vitrine_email_lead',
                  botaoTexto: 'Ver minha seleção personalizada →',
                  leadId: lead.id
                });
                _leads[i].vitrineEmailEnviada = true;
                _leads[i].vitrineEmailEnviadaEm = new Date().toISOString();
                console.log('[VITRINE EMAIL] enviado para:', _emailLead);
                consumir(_leads[i].userId || _leads[i].corretorId, 'email_lead').catch(()=>{});
              } catch(_eVit){ console.error('[VITRINE EMAIL] erro:', _eVit.message); }
            }
          }

        } else if (fu.tipo === 'followup_vitrine') {
          // Proteção — não envia se já tem visita agendada
          const _jaTemVisita = _leads[i].visitaSolicitada || (_leads[i].visitaStatus && !['cancelada','recusada'].includes(_leads[i].visitaStatus||''));
          if (_jaTemVisita) { console.log('[JOB FU] followup_vitrine ignorado — visita ja agendada:', lead.nome); continue; }
          _leads[i].waFollowupVitrineEnviadoEm = new Date().toISOString();
          const _link = BASE_URL + '/cliente/oferta/' + lead.id + '?userId=' + _userId;
          const _nomeCorretor = _user && _user.nome ? _user.nome : 'Seu corretor';
          const _qtdMatches = (_leads[i].matchesAuto || _leads[i].matches || []).length;
          const _msg = 'Oi ' + (lead.nome || '') + '! Vi que ainda nao agendou uma visita.\n\n'
            + 'Separamos ' + _qtdMatches + ' imovel(is) para voce. Entre no link, escolha o que mais gostou e solicite a visita:\n\n'
            + _link + '\n\n'
            + 'Caso ja esteja conversando com ' + _nomeCorretor + ', pode desconsiderar esta mensagem. '
            + 'Mas se quiser, pode entrar no link e agendar diretamente por la! 😊';
          await _enviarWA(_instancia, _contato, _msg);
          const _emailFU = lead.email || '';
          if (_emailFU) { try { const { enviarEmail: _eEFU } = require('./services/email'); await _eEFU({ para: _emailFU, assunto: '🏠 Seus imóveis estão esperando por você!', html: '<div style="font-family:Arial,sans-serif;max-width:600px;padding:32px"><pre style="font-family:Arial,sans-serif;white-space:pre-wrap">' + _msg + '</pre></div>', texto: _msg }); consumir(_leads[i].userId || _leads[i].corretorId, 'email_lead').catch(()=>{}); } catch(_eFU){} }

        } else if (fu.tipo === 'qualificar_lead') {
          // DESATIVADO — qualificação agora é imediata no webhook
          console.log('[JOB FU] qualificar_lead ignorado — já enviado pelo webhook:', lead.nome);

        } else if (fu.tipo === 'agendar_visita') {
          _leads[i].waAgendarVisitaEnviadoEm = new Date().toISOString();
          const _imovel = (_leads[i].matchesAuto || _leads[i].matches || [])[0];
          const _msg = 'Olá ' + (lead.nome || '') + '! Que tal agendarmos uma visita? 🏠\n\n'
            + (_imovel ? 'Temos ' + _imovel.tipo + ' em ' + _imovel.bairro + ' disponível.\n\n' : '')
            + 'Qual dia e horário ficaria melhor para você?';
          await _enviarWA(_instancia, _contato, _msg);
          const _emailFU = lead.email || '';
          if (_emailFU) { try { const { enviarEmail: _eEFU } = require('./services/email'); await _eEFU({ para: _emailFU, assunto: '📅 Que tal agendar uma visita?', html: '<div style="font-family:Arial,sans-serif;max-width:600px;padding:32px"><pre style="font-family:Arial,sans-serif;white-space:pre-wrap">' + _msg + '</pre></div>', texto: _msg }); consumir(_leads[i].userId || _leads[i].corretorId, 'email_lead').catch(()=>{}); } catch(_eFU){} }

        } else if (fu.tipo === 'followup_visita') {
          _leads[i].waFollowupVisitaEnviadoEm = new Date().toISOString();
          const _msg = 'Olá ' + (lead.nome || '') + '! Como foi a visita? Gostou do imóvel? 🏠\n\nPosso te ajudar com alguma dúvida ou mostrar outras opções?';
          await _enviarWA(_instancia, _contato, _msg);
          const _emailFU = lead.email || '';
          if (_emailFU) { try { const { enviarEmail: _eEFU } = require('./services/email'); await _eEFU({ para: _emailFU, assunto: '🏠 Como foi a visita?', html: '<div style="font-family:Arial,sans-serif;max-width:600px;padding:32px"><pre style="font-family:Arial,sans-serif;white-space:pre-wrap">' + _msg + '</pre></div>', texto: _msg }); consumir(_leads[i].userId || _leads[i].corretorId, 'email_lead').catch(()=>{}); } catch(_eFU){} }

        } else if (fu.tipo === 'proposta_negocio') {
          _leads[i].waPropostaEnviadoEm = new Date().toISOString();
          const _msg = 'Olá ' + (lead.nome || '') + '! Ótimo momento para darmos o próximo passo! 🎯\n\nVocê tem interesse em fazer uma proposta? Posso te ajudar com todo o processo.';
          await _enviarWA(_instancia, _contato, _msg);
        }

        console.log('[JOB FU] ✓ tipo:', fu.tipo, '| lead:', lead.nome || _contato);
      }

      if (_mudou) _salvou = true;
    }

    if (_salvou) {
      salvarTodosLeads(_leads).catch(e=>console.error("[leads]",e.message));
      console.log('[JOB FU] leads atualizados');
    }
  } catch(e) {
    console.error('[JOB FU] erro geral:', e.message);
  }
}, 5 * 60 * 1000); // roda a cada 5 minutos
// ── FIM JOB_FOLLOWUPS ────────────────────────────────────────────────────────

// ── JOB_JOBS_TRAVADOS — relança import de XML/leads e disparos WhatsApp que ──
// ficaram presos em "processando"/"enviando" (worker_thread morto no meio de um
// deploy — o Render manda SIGTERM na instância antiga, mas worker_threads não
// recebem esse sinal e são encerrados abruptamente junto do processo pai,
// deixando o job/campanha "travado" pra sempre sem essa checagem). Roda a cada
// 5 min (mesma cadência do JOB_FOLLOWUPS), só mexe em quem está sem atualização
// há 10+ min e ainda não foi relançado 2x (evita loop em job com causa real de
// erro, ex.: arquivo/URL que não existe mais).
setInterval(async () => {
  try {
    const { listarJobsTravados, atualizarJob } = require('./services/importJobs');
    const { dispararWorkerXml, dispararWorkerLeads } = require('./services/workerDispatch');
    const _jobsTravados = await listarJobsTravados(10, 2);
    for (const job of _jobsTravados) {
      console.log('[JOB TRAVADOS] relançando import job:', job.id, '| tipo:', job.tipo, '| relancamentos:', job.relancamentos || 0);
      await atualizarJob(job.id, { relancamentos: (job.relancamentos || 0) + 1 });
      if (job.tipo === 'xml') {
        dispararWorkerXml(job.id, job.arquivo, job.usuario_id);
      } else if (job.tipo === 'csv') {
        dispararWorkerLeads(job.id, job.arquivo, job.usuario_id);
      }
    }
  } catch(e) {
    console.error('[JOB TRAVADOS] erro import_jobs:', e.message);
  }

  try {
    const { listarCampanhasTravadas, atualizarCampanha } = require('./services/salvarDisparo');
    const { dispararWorkerDisparo } = require('./services/workerDispatch');
    const _campanhasTravadas = await listarCampanhasTravadas(10, 2);
    for (const campanha of _campanhasTravadas) {
      console.log('[JOB TRAVADOS] relançando disparo:', campanha.id, '| nome:', campanha.nome_campanha, '| relancamentos:', campanha.relancamentos || 0);
      await atualizarCampanha(campanha.id, { relancamentos: (campanha.relancamentos || 0) + 1 });
      dispararWorkerDisparo(campanha.id);
    }
  } catch(e) {
    console.error('[JOB TRAVADOS] erro disparos_campanhas:', e.message);
  }

  // Campanhas com restringir_horario=true que pararam fora da janela
  // (12h-13h/20h-21h Brasília) — assim que a janela abrir de novo, relança
  // o worker pra continuar de onde parou.
  try {
    const { listarCampanhasAguardandoJanela, dentroDaJanelaDisparo } = require('./services/salvarDisparo');
    if (dentroDaJanelaDisparo()) {
      const { dispararWorkerDisparo } = require('./services/workerDispatch');
      const _aguardandoJanela = await listarCampanhasAguardandoJanela();
      for (const campanha of _aguardandoJanela) {
        console.log('[JOB TRAVADOS] janela aberta, relançando disparo:', campanha.id, '| nome:', campanha.nome_campanha);
        dispararWorkerDisparo(campanha.id);
      }
    }
  } catch(e) {
    console.error('[JOB TRAVADOS] erro janela disparos:', e.message);
  }

}, 5 * 60 * 1000); // roda a cada 5 minutos

// ── JOB_DISTRIBUICAO_SUBADMIN — round-robin automático entre sub-admins ──────
// Campanha de Captação e Campanha de E-mail (corretores) — antes só rodava
// manual (botão "Distribuir agora"). Separado do JOB_JOBS_TRAVADOS de propósito:
// aquele é um setInterval puro, sem primeira execução no boot — só dispara depois
// de 5min rodando. Com deploy frequente (Render reinicia o processo a cada push),
// o timer não dava tempo de completar o primeiro ciclo antes do próximo restart,
// e esse job efetivamente nunca rodava (bug real: só 1 contato tinha sido
// distribuído depois de várias horas de campanha ativa). Aqui roda 1x logo no
// boot (15s de atraso, pra deixar o resto da inicialização assentar) + repete a
// cada 5min. Idempotente (distribuirAtendimentosAbertos só mexe em quem tá com
// atendido_por vazio), então rodar logo e com frequência é seguro.
// Registra CADA execução (rodou ou não, achou conta ativa ou não, quantos
// distribuiu) numa tabela simples — sem isso não tinha como confirmar de
// fora se o job realmente tá rodando ou só "parece" que devia estar (foi
// exatamente esse tipo de dúvida que gerou idas e voltas — agora dá pra
// olhar direto em /admin/atribuicoes-subadmin ou consultar a tabela).
// Solta atendido_por de contato preso numa conta que não tem (ou perdeu) a
// permissão daquela campanha — sem isso o round-robin nunca redistribuía,
// porque distribuirAtendimentosAbertos só mexe em quem está com atendido_por
// vazio. tabela é sempre um literal fixo abaixo, nunca vem de request.
async function _liberarSemPermissao(tabela, contasValidas) {
  const { query: _qLib } = require('./services/db');
  const usuariosValidos = new Set(contasValidas.map(c => c.usuario));
  const { rows } = await _qLib(`SELECT id, atendido_por FROM ${tabela} WHERE atendido_por IS NOT NULL AND atendido_por != ''`);
  const semPermissao = rows.filter(r => !usuariosValidos.has(r.atendido_por)).map(r => r.id);
  if (!semPermissao.length) return 0;
  await _qLib(`UPDATE ${tabela} SET atendido_por=NULL, atendido_por_nome=NULL, atendido_por_cor=NULL, atendido_em=NULL WHERE id = ANY($1)`, [semPermissao]);
  return semPermissao.length;
}
async function _registrarStatusJobDistribuicao(detalhe) {
  try {
    const { query: _qJobStatus } = require('./services/db');
    await _qJobStatus(`CREATE TABLE IF NOT EXISTS job_status (id TEXT PRIMARY KEY, atualizado_em TIMESTAMP DEFAULT NOW(), detalhe TEXT)`);
    await _qJobStatus(
      `INSERT INTO job_status (id, atualizado_em, detalhe) VALUES ('distribuicao_subadmin', NOW(), $1)
       ON CONFLICT (id) DO UPDATE SET atualizado_em=NOW(), detalhe=$1`,
      [detalhe]
    );
  } catch (e) { console.error('[JOB DISTRIBUICAO] erro ao registrar status:', e.message); }
}
async function _rodarDistribuicaoSubAdmin() {
  try {
    const { listarAdminContas } = require('./services/salvarAdminConta');
    const _todasContasAtivas = (await listarAdminContas()).filter(c => c.ativo);
    if (!_todasContasAtivas.length) {
      await _registrarStatusJobDistribuicao('rodou, mas 0 sub-admin ativo em /admin/contas-admin — nada foi distribuído');
      return;
    }
    // Cada campanha só pode distribuir pra quem tem a permissão daquela
    // página marcada em /admin/contas-admin — sem isso um sub-admin sem
    // acesso a 'campanha'/'captacao-campanha' ainda recebia contato na régua
    // (só não conseguia ver a lista, mas o round-robin não sabia disso).
    const _contasCaptAuto = _todasContasAtivas.filter(c => (c.permissoes || []).includes('captacao-campanha'));
    const _contasEmailAuto = _todasContasAtivas.filter(c => (c.permissoes || []).includes('campanha'));

    const _liberadosCaptAuto = await _liberarSemPermissao('campanha_captacao_envios', _contasCaptAuto);
    const _liberadosEmailAuto = await _liberarSemPermissao('campanha_contatos', _contasEmailAuto);
    if (_liberadosCaptAuto > 0) console.log('[JOB DISTRIBUICAO] captação: liberados de conta sem permissão ->', _liberadosCaptAuto);
    if (_liberadosEmailAuto > 0) console.log('[JOB DISTRIBUICAO] campanha e-mail: liberados de conta sem permissão ->', _liberadosEmailAuto);

    let _resultCaptAuto = { distribuidos: 0 };
    let _resultCaptDiretaAuto = { distribuidos: 0 };
    if (_contasCaptAuto.length) {
      const { distribuirAtendimentosAbertos: _distribuirCaptAuto, distribuirCaptacaoDireta: _distribuirCaptDiretaAuto } = require('./services/campanhaCaptacao');
      _resultCaptAuto = await _distribuirCaptAuto(_contasCaptAuto);
      if (_resultCaptAuto.distribuidos > 0) console.log('[JOB DISTRIBUICAO] captação: distribuídos automaticamente ->', _resultCaptAuto.distribuidos);
      // Captações do link fixo /captar/REN-G9K6 sem passar pela campanha de
      // e-mail (ver nota em distribuirCaptacaoDireta) — mesma permissão
      // 'captacao-campanha', job/cadência compartilhados.
      _resultCaptDiretaAuto = await _distribuirCaptDiretaAuto(_contasCaptAuto);
      if (_resultCaptDiretaAuto.distribuidos > 0) console.log('[JOB DISTRIBUICAO] captação direta: distribuídos automaticamente ->', _resultCaptDiretaAuto.distribuidos);
    }

    let _resultEmailAuto = { distribuidos: 0 };
    if (_contasEmailAuto.length) {
      const { distribuirAtendimentosAbertos: _distribuirEmailAuto } = require('./services/campanha');
      _resultEmailAuto = await _distribuirEmailAuto(_contasEmailAuto);
      if (_resultEmailAuto.distribuidos > 0) console.log('[JOB DISTRIBUICAO] campanha e-mail: distribuídos automaticamente ->', _resultEmailAuto.distribuidos);
    }

    await _registrarStatusJobDistribuicao(`rodou com ${_todasContasAtivas.length} sub-admin(s) ativo(s) (${_contasCaptAuto.length} c/ permissão captação, ${_contasEmailAuto.length} c/ permissão e-mail) — liberados sem permissão: captação ${_liberadosCaptAuto}, e-mail ${_liberadosEmailAuto} — distribuídos: captação +${_resultCaptAuto.distribuidos}, captação direta +${_resultCaptDiretaAuto.distribuidos}, e-mail +${_resultEmailAuto.distribuidos}`);
  } catch(e) {
    console.error('[JOB DISTRIBUICAO] erro:', e.message);
    await _registrarStatusJobDistribuicao('ERRO: ' + e.message);
  }
}
setTimeout(_rodarDistribuicaoSubAdmin, 15000);
setInterval(_rodarDistribuicaoSubAdmin, 5 * 60 * 1000);
// ── FIM JOB_DISTRIBUICAO_SUBADMIN ────────────────────────────────────────────
