const _CAMPANHA_TAMANHO_PAGINA = 200;
app.get('/admin/campanha/contatos', authAdmin, async (req, res) => {
  try {
    const pagina = parseInt(req.query.pagina)||1;
    const q = req.query.q||'';
    const status = req.query.status||'';
    const subadmin = req.query.subadmin||'';
    const offset = (pagina-1)*_CAMPANHA_TAMANHO_PAGINA;
    let where = 'WHERE 1=1';
    const params = [];
    // Sub-admin só vê os contatos que ele mesmo atende (manual ou distribuído
    // em /admin/campanha/distribuir-atendimentos) — superadmin continua vendo
    // a base inteira, sem esse filtro. O filtro "subadmin" da UI só vale pro
    // superadmin (pra achar/auditar o que é de um sub-admin específico) — pra
    // conta secundária, o escopo já vem forçado acima e esse filtro é ignorado.
    if (req.session.adminSuper === false) {
      params.push(req.session.adminUsuario || '');
      where += ` AND atendido_por = $${params.length}`;
    } else if (subadmin === '_nenhum') {
      where += ` AND (atendido_por IS NULL OR atendido_por = '')`;
    } else if (subadmin) {
      params.push(subadmin); where += ` AND atendido_por = $${params.length}`;
    }
    if(q){ params.push('%'+q+'%'); where += ` AND (nome ILIKE $${params.length} OR email ILIKE $${params.length} OR celular ILIKE $${params.length})`; }
    if(status === 'abriu'){ where += ` AND aberto_em IS NOT NULL`; }
    else if(status === 'clicou'){ where += ` AND clicado_em IS NOT NULL`; }
    else if(status === 'cadastrou'){ where += ` AND LOWER(email) IN (SELECT LOWER(email) FROM usuarios WHERE email IS NOT NULL AND email != '')`; }
    else if(status === 'comprou'){ where += ` AND LOWER(email) IN (SELECT LOWER(email) FROM usuarios WHERE COALESCE(match_coins_total,0) > 1000)`; }
    else if(status === 'followup1'){ where += ` AND followup1_enviado_em IS NOT NULL`; }
    else if(status === 'followup2'){ where += ` AND followup2_enviado_em IS NOT NULL`; }
    else if(status === 'followup3'){ where += ` AND followup3_enviado_em IS NOT NULL`; }
    else if(status === 'sem_followup'){ where += ` AND followup1_enviado_em IS NULL AND followup2_enviado_em IS NULL AND followup3_enviado_em IS NULL`; }
    else if(status){ params.push(status); where += ` AND status=$${params.length}`; }
    params.push(_CAMPANHA_TAMANHO_PAGINA); params.push(offset);
    // "comprou": não tem sinal direto de compra de combo, então usa como
    // proxy o saldo total (match_coins_total) passar do bônus de boas-vindas
    // (1000) — se passou, recarregou em algum momento (ver conversa jul/2026,
    // decidido usar esse critério em vez de cruzar com Mercado Pago por ora).
    // "celular": se o contato virou usuário cadastrado, mostra o celular DA
    // CONTA (sempre o mais atual, lido ao vivo) em vez do celular importado
    // na planilha original — a planilha pode estar desatualizada, mas o
    // e-mail nunca muda, então é o vínculo confiável pra achar o celular
    // certo. Sem conta cadastrada com celular preenchido, mantém o da planilha.
    const { rows } = await require('./services/db').query(`SELECT id,nome,email,status,modelo_usado,aberto_em,clicado_em,enviado_em,erro,
      followup1_enviado_em,followup2_enviado_em,followup3_enviado_em,
      atendido_por,atendido_por_nome,atendido_por_cor,atendido_em,wa_manual_enviado_em,
      COALESCE(
        (SELECT celular FROM usuarios WHERE LOWER(email)=LOWER(campanha_contatos.email) AND celular IS NOT NULL AND celular != '' LIMIT 1),
        campanha_contatos.celular
      ) AS celular,
      (LOWER(email) IN (SELECT LOWER(email) FROM usuarios WHERE email IS NOT NULL AND email != '')) AS cadastrou,
      COALESCE((SELECT match_coins_total FROM usuarios WHERE LOWER(email)=LOWER(campanha_contatos.email) LIMIT 1), 0) > 1000 AS comprou
      FROM campanha_contatos ${where}
      -- Quem já recebeu o WhatsApp manual (wa_manual_enviado_em) desce pro
      -- final da lista — critério de ordenação MAIS externo, na frente até
      -- da prioridade de elegibilidade abaixo, pra sumir de cima assim que o
      -- sub-admin clica "Enviar" e sobrar só quem ainda falta mandar (ago/2026).
      ORDER BY (wa_manual_enviado_em IS NULL) DESC,
      (
        COALESCE(
          (SELECT celular FROM usuarios WHERE LOWER(email)=LOWER(campanha_contatos.email) AND celular IS NOT NULL AND celular != '' LIMIT 1),
          campanha_contatos.celular
        ) IS NOT NULL
        AND COALESCE(
          (SELECT celular FROM usuarios WHERE LOWER(email)=LOWER(campanha_contatos.email) AND celular IS NOT NULL AND celular != '' LIMIT 1),
          campanha_contatos.celular
        ) <> ''
        AND NOT (COALESCE((SELECT match_coins_total FROM usuarios WHERE LOWER(email)=LOWER(campanha_contatos.email) LIMIT 1), 0) > 1000)
        AND (
          (LOWER(email) IN (SELECT LOWER(email) FROM usuarios WHERE email IS NOT NULL AND email != ''))
          OR clicado_em IS NOT NULL OR aberto_em IS NOT NULL
        )
      ) DESC,
        COALESCE(enviado_em, criado_em) DESC
      LIMIT $${params.length-1} OFFSET $${params.length}`, params);
    const { rows: tot } = await require('./services/db').query(`SELECT COUNT(*) as total FROM campanha_contatos ${where}`, params.slice(0,-2));
    // Token do link de opt-out de WhatsApp — gerado aqui (não no cliente,
    // que não pode ver o segredo) e embutido na mensagem que o sub-admin
    // manda (ver _whatsappMensagem no <script> abaixo).
    const contatos = rows.map(c => ({ ...c, optoutToken: _waOptOutToken('campanha', c.id) }));
    res.json({ ok:true, contatos, total:tot[0].total });
  } catch(e){ res.json({ ok:false, erro:e.message }); }
});

// Registra quem clicou pra falar com esse contato pelo WhatsApp (colore a
// linha na tela e evita 2 pessoas chamando o mesmo lead — ver marcarAtendido
// em services/campanha.js). Qualquer conta com permissão 'campanha' pode
// atender (já é o que vê o bloco "Contatos importados"), não é ação restrita
// ao superadmin.
app.post('/admin/campanha/contatos/:id/atender', authAdmin, async (req, res) => {
  try {
    const { marcarAtendido } = require('./services/campanha');
    const resultado = await marcarAtendido(req.params.id, {
      por: req.session.adminUsuario || '',
      nome: req.session.adminNome || 'Admin',
      cor: req.session.adminCor || '#6b7280'
    });
    res.json(resultado);
  } catch (e) { res.json({ ok: false, erro: e.message }); }
});

// Marca que o botão de WhatsApp manual foi clicado de fato (mensagem aberta
// pra envio) — separado de /atender (que só marca "de quem é esse contato").
// Chamado a cada clique no botão, pra distinguir na tela quem já foi
// contactado de quem ainda não foi (pedido do Renato, ago/2026).
app.post('/admin/campanha/contatos/:id/wa-enviado', authAdmin, async (req, res) => {
  try {
    const { marcarWhatsappManualEnviado } = require('./services/campanha');
    await marcarWhatsappManualEnviado(req.params.id);
    res.json({ ok: true });
  } catch (e) { res.json({ ok: false, erro: e.message }); }
});

// Número pode ter sido reciclado pra outra pessoa, ou o lead pediu pra não
// receber mais WhatsApp — apaga só o celular (e-mail e histórico continuam
// intactos). Mesma permissão do botão de atender.
app.post('/admin/campanha/contatos/:id/excluir-celular', authAdmin, async (req, res) => {
  try {
    const { excluirCelularContato } = require('./services/campanha');
    await excluirCelularContato(req.params.id);
    res.json({ ok: true });
  } catch (e) { res.json({ ok: false, erro: e.message }); }
});

// Divide os contatos que clicaram e ainda estão sem atendente entre os
// sub-admins ativos — restrito ao superadmin (ver _ADMIN_ROTAS_SUPERADMIN_ONLY)
// porque é uma ação em lote que muda o dono de vários contatos de uma vez.
app.post('/admin/campanha/distribuir-atendimentos', authAdmin, async (req, res) => {
  try {
    const { listarAdminContas } = require('./services/salvarAdminConta');
    const contasAtivas = (await listarAdminContas()).filter(c => c.ativo && (c.permissoes || []).includes('campanha'));
    if (!contasAtivas.length) return res.json({ ok: false, erro: 'Nenhum sub-admin ativo com permissão de Campanha Email pra distribuir' });
    const liberados = await _liberarSemPermissao('campanha_contatos', contasAtivas);
    const { distribuirAtendimentosAbertos } = require('./services/campanha');
    const resultado = await distribuirAtendimentosAbertos(contasAtivas);
    res.json({ ok: true, ...resultado, liberadosSemPermissao: liberados });
  } catch (e) { res.json({ ok: false, erro: e.message }); }
});

// Mesma lógica acima, pra Campanha de Captação — restrito ao superadmin
// (ver _ADMIN_ROTAS_SUPERADMIN_ONLY).
app.post('/admin/captacao-campanha/distribuir-atendimentos', authAdmin, async (req, res) => {
  try {
    const { listarAdminContas } = require('./services/salvarAdminConta');
    const contasAtivas = (await listarAdminContas()).filter(c => c.ativo && (c.permissoes || []).includes('captacao-campanha'));
    if (!contasAtivas.length) return res.json({ ok: false, erro: 'Nenhum sub-admin ativo com permissão de Campanha Captação pra distribuir' });
    const liberados = await _liberarSemPermissao('campanha_captacao_envios', contasAtivas);
    const { distribuirAtendimentosAbertos } = require('./services/campanhaCaptacao');
    const resultado = await distribuirAtendimentosAbertos(contasAtivas);
    res.json({ ok: true, ...resultado, liberadosSemPermissao: liberados });
  } catch (e) { res.json({ ok: false, erro: e.message }); }
});

// Roda a distribuição de leads de interessados_portal por área de atuação
// (services/distribuicaoAreaAtuacao.js) na hora, sem esperar as 4h — só pra
// testar/conferir o resultado. Cobra créditos de verdade (mesmo custo de
// qualquer lead nova), por isso restrito ao superadmin. Ignora o guard de
// "já rodou hoje" de propósito (é a rota de teste manual).
app.post('/admin/distribuicao-area-atuacao/rodar', authAdmin, async (req, res) => {
  if (req.session.adminSuper === false) return res.status(403).json({ ok: false, erro: 'Só o superadmin pode rodar isso manualmente.' });
  try {
    const { distribuirLeadsPorArea } = require('./services/distribuicaoAreaAtuacao');
    const resultado = await distribuirLeadsPorArea();
    res.json({ ok: true, ...resultado });
  } catch (e) { res.json({ ok: false, erro: e.message }); }
});

// ── DISPAROS WHATSAPP (Meta Cloud API) ────────────────────────────────────────
// Sistema separado do Evolution API (usado pra vitrine/assistente) e da Campanha Email.
// Usa exclusivamente a WhatsApp Cloud API oficial da Meta (services/metaWhatsapp.js).
function _lerPlanilhaDisparo(filePath) {
  const XLSX = require('xlsx');
  const wb = XLSX.readFile(filePath);
  const ws = wb.Sheets[wb.SheetNames[0]];
  const linhas = XLSX.utils.sheet_to_json(ws, { defval: '' });
  const colunas = linhas.length ? Object.keys(linhas[0]) : [];
  return { colunas, linhas };
}

// Monta a lista de contatos a partir das linhas da planilha já mapeadas,
// barrando telefone inválido (célula vazia, texto lixo, número incompleto)
// antes de gastar tentativa de envio — usado tanto na criação da campanha
// quanto ao subir mais planilha numa campanha já existente.
function _prepararContatosDisparo(linhas, mapeamento) {
  const { _normalizarTelefone, _telefoneValido } = require('./services/metaWhatsapp');
  let numerosInvalidos = 0;
  const contatos = linhas
    .map(l => ({
      nome: mapeamento.nome ? String(l[mapeamento.nome] || '') : '',
      telefone: _normalizarTelefone(l[mapeamento.telefone]),
      variaveis: l
    }))
    .filter(c => {
      if (!c.telefone) return false;
      if (!_telefoneValido(c.telefone)) { numerosInvalidos++; return false; }
      return true;
    });
  return { contatos, numerosInvalidos };
}

